import time, sys, subprocess
from math import isqrt
import numpy as np

def cur(n):
    if n <= 2: return 0
    size = n // 2
    sieve = bytearray(b'\x01') * size
    sieve[0] = 0
    limit = isqrt(n - 1)
    for p in range(3, limit + 1, 2):
        if sieve[p >> 1]:
            start = (p * p) >> 1
            step = p
            sieve[start::step] = b'\x00' * (((size - 1 - start) // step) + 1)
    return sieve.count(1) + 1

def npv(n):
    if n <= 2: return 0
    s = np.ones(n, dtype=bool)
    s[:2] = False
    for p in range(2, isqrt(n - 1) + 1):
        if s[p]:
            s[p*p::p] = False
    return int(s.sum())

for n in [0,1,2,3,4,5,10,100,1000,100000]:
    assert cur(n) == npv(n), (n, cur(n), npv(n))
print('small ok')

for name, f in [('cur', cur), ('npv', npv)]:
    best = 1e9
    for _ in range(5):
        t = time.perf_counter(); r = f(5000000); best = min(best, time.perf_counter()-t)
    print(name, r, 'best', round(best,5), 'metric', round(1/best,1))
